package cart

// Item represents a product in the cart
type Item struct {
	Name     string
	Price    float64
	Quantity int
}

// ShoppingCart holds items for purchase
type ShoppingCart struct {
	items []Item
}

// NewShoppingCart creates an empty cart
func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: []Item{},
	}
}

// AddItem adds an item to the cart
func (c *ShoppingCart) AddItem(name string, price float64, quantity int) {
	for i, item := range c.items {
		if item.Name == name {
			c.items[i].Quantity += quantity
			return
		}
	}
	c.items = append(c.items, Item{Name: name, Price: price, Quantity: quantity})
}

// RemoveItem removes an item entirely from the cart
func (c *ShoppingCart) RemoveItem(name string) {
	for i, item := range c.items {
		if item.Name == name {
			c.items = append(c.items[:i], c.items[i+1:]...)
			return
		}
	}
}

// UpdateQuantity changes the quantity of an item
func (c *ShoppingCart) UpdateQuantity(name string, quantity int) {
	for i, item := range c.items {
		if item.Name == name {
			if quantity <= 0 {
				c.RemoveItem(name)
				return
			}
			c.items[i].Quantity = quantity
			return
		}
	}
}

// GetItems returns all items in the cart
func (c *ShoppingCart) GetItems() []Item {
	return c.items
}

// GetTotal calculates the total price
func (c *ShoppingCart) GetTotal() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

// ItemCount returns the total number of items
func (c *ShoppingCart) ItemCount() int {
	var count int
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

// Clear empties the cart
func (c *ShoppingCart) Clear() {
	c.items = []Item{}
}

// IsEmpty checks if cart has no items
func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}
```

